def largest_rect(mask):
    R,C=mask.shape; best=(0,None)
    # prefix sums
    P=np.zeros((R+1,C+1),int)
    P[1:,1:]=np.cumsum(np.cumsum(mask,0),1)
    for r0 in range(R):
        for r1 in range(r0,R):
            for c0 in range(C):
                for c1 in range(c0,C):
                    area=(r1-r0+1)*(c1-c0+1)
                    if area<=best[0]: continue
                    s=P[r1+1,c1+1]-P[r0,c1+1]-P[r1+1,c0]+P[r0,c0]
                    if s==area: best=(area,(r0,r1,c0,c1))
    return best
