def largest_square(mask):
    R,C=mask.shape; best=(0,None)
    P=np.zeros((R+1,C+1),int)
    P[1:,1:]=np.cumsum(np.cumsum(mask.astype(int),0),1)
    for s in range(min(R,C),0,-1):
        for r0 in range(R-s+1):
            for c0 in range(C-s+1):
                tot=P[r0+s,c0+s]-P[r0,c0+s]-P[r0+s,c0]+P[r0,c0]
                if tot==s*s: return (s,(r0,r0+s-1,c0,c0+s-1))
    return best
